#include "licentivo.h"
#include <stdio.h>
#include <stdlib.h>
int main(int argc,char**argv){FILE*f=fopen(argc>1?argv[1]:"tests/lease-vectors.json","rb");if(!f)return 1;char*b=calloc(131073,1);size_t n=fread(b,1,131072,f);fclose(f);b[n]=0;cJSON*fixture=ln_json(b);free(b);if(!fixture)return 1;const cJSON*keys=cJSON_GetObjectItemCaseSensitive(fixture,"trusted_keys");const cJSON*vectors=cJSON_GetObjectItemCaseSensitive(fixture,"vectors");int count=0;for(const cJSON*v=vectors->child;v;v=v->next){int ok=ln_verify(cJSON_GetObjectItemCaseSensitive(v,"envelope"),keys,cJSON_GetObjectItemCaseSensitive(v,"product_id")->valuestring,cJSON_GetObjectItemCaseSensitive(v,"device_id")->valuestring,(int64_t)cJSON_GetObjectItemCaseSensitive(v,"now")->valuedouble);if(ok!=cJSON_IsTrue(cJSON_GetObjectItemCaseSensitive(v,"valid"))){fprintf(stderr,"C vector failed: %s\n",cJSON_GetObjectItemCaseSensitive(v,"name")->valuestring);cJSON_Delete(fixture);return 1;}count++;}printf("C/C++ security core: %d lease vectors passed\n",count);cJSON_Delete(fixture);return 0;}
